//import 
import '../../../styles/acco.css';
//function
const Yaccopage1 = (props) => {
    return (
        <div className="accordion-container">
            <div className="accordion-item">
                <input type="checkbox" id="item1"/>
                 <label className="accordion-header" for="item1">
                {props.title}
                </label>
                <div className="accordion-body">
                    <strong>{props.dec}</strong>
                </div>
            </div>

        </div>
        
    )
}

//export
export default Yaccopage1
